        if (totalAmount == 0) return 0;
        uint256 yieldToDistribute = 0;
        for (uint256 i = 0; i < payoutAmounts.length; i++) {
            uint256 proportionalYield = calculateProportionalYield(
                totalYield,
                payoutAmounts[i],
                totalAmount
